class Solution {
  public Node flatten(Node head) {
    flattenTail(head);
    return head;
  }

  // flattens the list starting at node and returns its last node
  private Node flattenTail(Node node) {
    Node cur = node, last = node;
    while (cur != null) {
      Node next = cur.next;
      if (cur.child != null) {
        Node childTail = flattenTail(cur.child);
        cur.next = cur.child;
        cur.child.prev = cur;
        cur.child = null;
        childTail.next = next;
        if (next != null) next.prev = childTail;
        last = childTail;
      } else last = cur;
      cur = next;
    }
    return last;
  }
}
